using Xunit;

namespace Orleans.Core.Tests.Configuration
{
    public class OptionsOverridesTests
    {
        [Fact]
        public void GetOverridableOption_ShouldReturnKeyedService_WhenKeyedServiceExists()
        {
            // Arrange
            var mockServiceProvider = new Mock<IServiceProvider>();
            var mockKeyedService = new Mock<TestOptions>();
            mockServiceProvider.Setup(sp => sp.GetKeyedService<TestOptions>("testKey")).Returns(mockKeyedService.Object);

            // Act
            var result = OptionsOverrides.GetOverridableOption<TestOptions>(mockServiceProvider.Object, "testKey");

            // Assert
            Assert.NotNull(result);
            Assert.Equal(mockKeyedService.Object, result.Value);
        }

        [Fact]
        public void GetOverridableOption_ShouldReturnRequiredService_WhenKeyedServiceDoesNotExist()
        {
            // Arrange
            var mockServiceProvider = new Mock<IServiceProvider>();
            var mockRequiredService = new Mock<IOptions<TestOptions>>();
            mockServiceProvider.Setup(sp => sp.GetKeyedService<TestOptions>("testKey")).Returns((TestOptions)null);
            mockServiceProvider.Setup(sp => sp.GetRequiredService<IOptions<TestOptions>>()).Returns(mockRequiredService.Object);

            // Act
            var result = OptionsOverrides.GetOverridableOption<TestOptions>(mockServiceProvider.Object, "testKey");

            // Assert
            Assert.NotNull(result);
            Assert.Equal(mockRequiredService.Object, result);
        }

